class KnowledgeTriple(BaseModel):
    subject: str = Field(description='The subject of the triple (e.g. \'matrix multiplication\', \'Baye\'s theorem\', \'the Python `asyncio.gather` function\').')
    verb: str = Field(description='The relationship verb (e.g. \'is defined as\', \'has property\', \'is a prerequisite for\', \'is visualised by\').')
    object: str = Field(description='The object of the triple (e.g. \'a linear transformation over a vector space\', \'P(A|B) = P(B|A)P(A)/P(B)\', \'a coroutine scheduler\').')
    triple_kind: KnowledgeTripleKind = Field(description='Which typed category the triple belongs to.')
    confidence: float = Field(description='Confidence score in [0, 1]; the model\'s self-reported certainty.')
    source_frame_idx: typing.Optional[int] = Field(default=None, description='If extracted from a frame caption, the frame index (1-based). Null if from transcript.')
    source_segment_idx: typing.Optional[int] = Field(default=None, description='If extracted from a transcript segment, the segment index (1-based). Null if from frame.')

